H.background();
// Perfectly inelastic collision in 1D: the two carts STICK together. Momentum
// is conserved, but kinetic energy is LOST (to heat/deformation). They approach,
// collide at center, then travel as one combined lump at the common velocity vf.
const w = H.W, ht = H.H;
const m1 = Math.max(0.2, P.m1), m2 = Math.max(0.2, P.m2);
const u1 = P.v1, u2 = P.v2; // initial velocities (m/s)
const M = m1 + m2;
const vf = (m1 * u1 + m2 * u2) / M; // common velocity after sticking
const view = H.plot2d({ xMin: -10, xMax: 10, yMin: -3, yMax: 3, box: { x: 40, y: ht * 0.40, w: w - 80, h: ht * 0.34 } });
view.line(-10, -1.2, 10, -1.2, { color: H.colors.axis, width: 2 });
for (let gx = -10; gx <= 10; gx += 2) view.line(gx, -1.2, gx, -1.5, { color: H.colors.grid, width: 1 });
const period = 6.0, tc = 3.0;
const tt = t % period;
// Before tc each cart moves at its own speed; both reach x≈0 at tc, then the
// stuck pair drifts together at vf.
const X1 = tt < tc ? u1 * (tt - tc) : vf * (tt - tc);
const X2 = tt < tc ? u2 * (tt - tc) : vf * (tt - tc);
const r1 = 12 + 10 * Math.sqrt(m1), r2 = 12 + 10 * Math.sqrt(m2);
const cy = view.Y(-0.6);
const cx1 = view.X(H.clamp(X1, -9.5, 9.5));
const cx2 = view.X(H.clamp(X2, -9.5, 9.5));
H.circle(cx1, cy, r1 * 0.5, { fill: H.colors.accent, stroke: H.colors.bg, width: 2 });
H.circle(cx2, cy, r2 * 0.5, { fill: H.colors.accent2, stroke: H.colors.bg, width: 2 });
// After collision draw a bond linking them (they move as one body).
if (tt >= tc) H.line(cx1, cy, cx2, cy, { color: H.colors.violet, width: 3 });
const vNow1 = tt < tc ? u1 : vf, vNow2 = tt < tc ? u2 : vf;
H.arrow(cx1, cy - r1 * 0.5 - 8, cx1 + vNow1 * 14, cy - r1 * 0.5 - 8, { color: H.colors.accent, width: 2.5 });
H.arrow(cx2, cy - r2 * 0.5 - 8, cx2 + vNow2 * 14, cy - r2 * 0.5 - 8, { color: H.colors.accent2, width: 2.5 });
const pBefore = m1 * u1 + m2 * u2;
const pAfter = M * vf;
const keBefore = 0.5 * m1 * u1 * u1 + 0.5 * m2 * u2 * u2;
const keAfter = 0.5 * M * vf * vf;
const keLost = keBefore - keAfter;
H.text("Inelastic collision: p conserved, KE lost", 24, 30, { color: H.colors.ink, size: 18, weight: 700 });
H.text("vf = (m1 v1 + m2 v2) / (m1 + m2)     they stick and move together", 24, 52, { color: H.colors.sub, size: 12 });
H.text("before:  v1=" + u1.toFixed(1) + "  v2=" + u2.toFixed(1) + " m/s        after:  vf = " + vf.toFixed(2) + " m/s (both)", 24, ht - 56, { color: H.colors.ink, size: 13 });
H.text("p = " + pBefore.toFixed(2) + " → " + pAfter.toFixed(2) + " kg·m/s     KE = " + keBefore.toFixed(2) + " → " + keAfter.toFixed(2) + " J  (lost " + keLost.toFixed(2) + " J)", 24, ht - 34, { color: H.colors.warn, size: 13 });
H.legend([{ label: "m1 = " + m1.toFixed(1) + " kg", color: H.colors.accent }, { label: "m2 = " + m2.toFixed(1) + " kg", color: H.colors.accent2 }], w - 160, 28);
